import{_ as s,o as e,c as n,a0 as t}from"./chunks/framework.CNDWyMYS.js";const u=JSON.parse('{"title":"Recommended practices for Makefiles","description":"","frontmatter":{},"headers":[],"relativePath":"recommended_practices_for_makefiles.md","filePath":"recommended_practices_for_makefiles.md"}'),o={name:"recommended_practices_for_makefiles.md"};function i(l,a,p,r,c,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="recommended-practices-for-makefiles" tabindex="-1">Recommended practices for Makefiles <a class="header-anchor" href="#recommended-practices-for-makefiles" aria-label="Permalink to &quot;Recommended practices for Makefiles&quot;">​</a></h1><p>When authoring a Lua module, especially those containing C code, developers are always faced with some build and deployment issues: where to find libraries, where to install modules, which flags to pass when building, and so on. Looking at the existing modules available in the web, it is clear to see that there are no <em>de facto</em> standards in Makefiles for Lua modules, and that many of them are incomplete copies of one another, and many of them share the same deficiencies. Here is a list of some of those issues we found during the development of LuaRocks, and how to avoid them. Following the recommendations below will improve the portability of your Makefiles and make things easier for writing rocks, other packagers such as Linux distributions, and your users.</p><h1 id="do-not-ask-users-to-edit-files-by-hand" tabindex="-1">Do not ask users to edit files &quot;by hand&quot; <a class="header-anchor" href="#do-not-ask-users-to-edit-files-by-hand" aria-label="Permalink to &quot;Do not ask users to edit files &quot;by hand&quot;&quot;">​</a></h1><p>Asking users to hand-edit things is error-prone. Even though systems like LuaRocks support applying patches -- which is the automated equivalent of hand-tweaking files -- this adds maintenance burden, as patches have to be updated on each release if any change happens in the file. Always use variables, so that they can be overridden by automated processes. Hand-tweaks in the code can be avoided by propagating C defines from Makefiles as well.</p><p>Don&#39;t:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Edit this to suit your installation</span></span>
<span class="line"><span>const char* bla_dir = &quot;/usr/local/share/bla&quot;;</span></span></code></pre></div><p>Do:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BLA_DIR=/usr/local/share/bla</span></span>
<span class="line"><span># ...</span></span>
<span class="line"><span>bla.o:</span></span>
<span class="line"><span>        $(CC) -c bla.c -DBLA_DIR=\\&quot;$(BLA_DIR)\\&quot;</span></span></code></pre></div><h2 id="do-not-hardcode-any-paths" tabindex="-1">Do not hardcode any paths <a class="header-anchor" href="#do-not-hardcode-any-paths" aria-label="Permalink to &quot;Do not hardcode any paths&quot;">​</a></h2><p>This is a corollary to the above recommendation, really. Whenever you are passing any paths, don&#39;t write them directly in Makefile rules. Always factor them out into variables.</p><h1 id="provide-a-nice-install-rule" tabindex="-1">Provide a nice &quot;install&quot; rule <a class="header-anchor" href="#provide-a-nice-install-rule" aria-label="Permalink to &quot;Provide a nice &quot;install&quot; rule&quot;">​</a></h1><p>A large number of Makefiles for Lua modules ship without an &quot;install&quot; rule, probably due to the long-standing lack of standard install locations for modules that plagued the Lua world in the past. Nowadays, however, the convention of using .../lib/lua/5.1/ for C modules and .../share/lua/5.1/ for Lua modules (relative to the prefix where Lua is installed) is well established, and there is no reason not to use it. To make things even easier for your users, you can also factor out the common Lua prefix. /usr/local is a good default, since it is also the default for the vanilla Lua tarball.</p><p>Don&#39;t:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># no make install rule!</span></span></code></pre></div><p>Do:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LUA_DIR=/usr/local</span></span>
<span class="line"><span>LUA_LIBDIR=$(LUA_DIR)/lib/lua/5.1</span></span>
<span class="line"><span>LUA_SHAREDIR=$(LUA_DIR)/share/lua/5.1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>install:</span></span>
<span class="line"><span>        mkdir -p $(LUA_LIBDIR)/bla</span></span>
<span class="line"><span>        cp bla/core.so $(LUA_LIBDIR)/bla</span></span>
<span class="line"><span>        mkdir -p $(LUA_SHAREDIR)/bla</span></span>
<span class="line"><span>        cp bla.lua $(LUA_SHAREDIR)</span></span>
<span class="line"><span>        cp bla/extras.lua $(LUA_SHAREDIR)/bla</span></span></code></pre></div><p>Some packagers recommend prepending an empty <code>$(DESTDIR)</code> variable to all target paths in your install rule, but that&#39;s not strictly necessary if your paths are all set into variables, which can be redefined for the &quot;make install&quot; run, like in the example above.</p><h1 id="do-not-assume-libraries-are-in-the-system-path" tabindex="-1">Do not assume libraries are in the system path <a class="header-anchor" href="#do-not-assume-libraries-are-in-the-system-path" aria-label="Permalink to &quot;Do not assume libraries are in the system path&quot;">​</a></h1><p>If your program uses LibPNG, adding &quot;-lpng&quot; to your Makefile is not enough. Your users may have the LibPNG library somewhere else, so let them specify the locations of both the libraries and headers. The default values you pick are not really important, as long as they&#39;re overridable by the user, but /usr/local is always a good choice on Unix systems as this is the first typical &quot;non-system path&quot; that users may want to use.</p><p>Of course, use one library per value; don&#39;t assume all third-party libraries can be found in the same place.</p><p>Don&#39;t:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -o bla bla.c -lpng</span></span></code></pre></div><p>Do:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LIBPNG_DIR=/usr/local</span></span>
<span class="line"><span>LIBPNG_INCDIR=$(LIBPNG_DIR)/include</span></span>
<span class="line"><span>LIBPNG_LIBDIR=$(LIBPNG_DIR)/lib</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ...</span></span>
<span class="line"><span>        $(CC) -o bla bla.c -lpng -L$(LIBPNG_LIBDIR) -I$(LIBPNG_INCDIR)</span></span></code></pre></div><h1 id="avoid-compiler-assumptions" tabindex="-1">Avoid compiler assumptions <a class="header-anchor" href="#avoid-compiler-assumptions" aria-label="Permalink to &quot;Avoid compiler assumptions&quot;">​</a></h1><p>Even if your code only compiles in GCC and is Unix-only, there are still build portability issues to look out for. The main ones are:</p><ul><li><p><strong>Not all GCCs link libraries with the same flags</strong> - for instance, linking shared libraries is done with &quot;-shared&quot; on Linux and &quot;-bundle -undefined dynamic_lookup -all_load&quot; on Mac OSX. Factoring the flags in a variable is a nice gesture for users of other operating systems. (LuaRocks can take care of the detection part and set the flag appropriately, but packages of other systems will benefit as well.)</p></li><li><p><strong>The compiler is not always called &quot;gcc&quot;</strong> - this one is for the people in the embedded world; in their toolchains, their cross-compilers often have names like &quot;arm-nofpu-gcc&quot;. $(CC) is a standard variable in make. Just use that instead of &quot;gcc&quot; and you&#39;re good to go.</p></li></ul><p>Don&#39;t:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bla.so:</span></span>
<span class="line"><span>        gcc -o bla.so -shared bla.o</span></span></code></pre></div><p>Do:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LIBFLAG=-shared</span></span>
<span class="line"><span># ...</span></span>
<span class="line"><span>bla.so:</span></span>
<span class="line"><span>        $(CC) -o bla.so $(LIBFLAG) bla.o</span></span></code></pre></div><h1 id="do-not-overload-variables" tabindex="-1">Do not &quot;overload&quot; variables <a class="header-anchor" href="#do-not-overload-variables" aria-label="Permalink to &quot;Do not &quot;overload&quot; variables&quot;">​</a></h1><p>As mentioned in the topic about third-party libraries above, don&#39;t reuse variables just because two conceptually different locations happen to point to the same place. For example, do not assume that the directory you&#39;re using to <em>find</em> libraries and the directory you&#39;re <em>installing</em> libraries to is the same. That little economy will only cause confusion and trouble to your users.</p><p>Don&#39;t:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LIBDIR=/usr/local/lib</span></span>
<span class="line"><span>INCDIR=/usr/local/include</span></span>
<span class="line"><span># ...</span></span>
<span class="line"><span>bla.so:</span></span>
<span class="line"><span>        $(CC) $(LIBFLAG) -o bla.so -lpng -L$(LIBDIR) -I$(INCDIR)</span></span>
<span class="line"><span>install:</span></span>
<span class="line"><span>        mkdir -p $(LIBDIR)</span></span>
<span class="line"><span>        cp bla.so $(LIBDIR)/lua/5.1</span></span></code></pre></div><p>Do:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LIBPNG_DIR=/usr/local</span></span>
<span class="line"><span>LIBPNG_LIBDIR=$(LIBPNG_DIR)/lib</span></span>
<span class="line"><span>LIBPNG_INCDIR=$(LIBPNG_DIR)/include</span></span>
<span class="line"><span>LUA_DIR=/usr/local</span></span>
<span class="line"><span>LUA_LIBDIR=$(LUA_DIR)/lib/lua/5.1</span></span>
<span class="line"><span># ...</span></span>
<span class="line"><span>bla.so:</span></span>
<span class="line"><span>        $(CC) $(LIBFLAG) -o bla.so -lpng -L$(LIBPNG_LIBDIR) -I$(LIBPNG_INCDIR)</span></span>
<span class="line"><span>install:</span></span>
<span class="line"><span>        mkdir -p $(LUA_LIBDIR)</span></span>
<span class="line"><span>        cp bla.so $(LUA_LIBDIR)</span></span></code></pre></div>`,37)])])}const b=s(o,[["render",i]]);export{u as __pageData,b as default};
